use serde_json::{json,Value};use std::{fs,process::Command};
fn main(){let r="/tmp/zopro-current-c7a-20261027";let p=format!("{r}/image-manifest.json");let mut m:Value=serde_json::from_slice(&fs::read(&p).unwrap()).unwrap();assert_eq!(m["local_gnark_proofs"],27);assert_eq!(m["local_preflight_sdk"],108);let old=m["image_tag"].as_str().unwrap().to_owned();assert!(old.starts_with("555415002830.dkr.ecr.eu-north-1.amazonaws.com/"));let new=old.replacen("555415002830","558215002830",1);assert!(Command::new("docker").args(["tag",&old,&new]).status().unwrap().success());let out=Command::new("docker").args(["image","inspect",&new,"--format","{{.Id}}"] ).output().unwrap();assert!(out.status.success());assert_eq!(String::from_utf8(out.stdout).unwrap().trim(),m["image_id"].as_str().unwrap());m["image_tag"]=json!(new);m["tag_repair_only_no_new_image_or_proofs"]=json!(true);fs::write(p,serde_json::to_vec_pretty(&m).unwrap()).unwrap();fs::write(format!("{r}/publication-repair.json"),serde_json::to_vec_pretty(&json!({"stage":"publication after successful27Gnark/108SDK preflight;before any instance","cause":"helper globally replaced inventory82with54, also changing account digits in finalizer image tag","repair":"exact inventory-expression substitution and correct registry-account tag on same immutable image","image_id_unchanged":true,"prover_or_runner_changed":false,"successful_capture_repeated":false,"failed_push_created_instance":false,"failed_docker_auth_directory_removed":true})).unwrap()).unwrap();println!("Corrected only destination tag; image ID and all27proofs unchanged");}
